class Solution:
    def minCut(self, s: str) -> int:
        n = len(s)
        # pal[i][j]：s[i..j] 是否回文，i 要倒着推才能用到内层结果
        pal = [[False] * n for _ in range(n)]
        for i in range(n - 1, -1, -1):
            for j in range(i, n):
                if s[i] == s[j] and (j - i <= 2 or pal[i + 1][j - 1]):
                    pal[i][j] = True
        # dp[i]：前 i 个字符的最少切割数，dp[0] 是空串
        dp = [0] * (n + 1)
        for i in range(1, n + 1):
            dp[i] = i - 1
            if pal[0][i - 1]:
                dp[i] = 0
                continue
            for j in range(1, i):
                if pal[j][i - 1]:
                    dp[i] = min(dp[i], dp[j] + 1)
        return dp[n]

