class Solution:
    def maxProfit(self, k: int, prices: List[int]) -> int:
        n = len(prices)
        if n == 0 or k == 0:
            return 0
        NEG = -10 ** 18
        # dp[j][0]：至多 j 次额度且空仓；dp[j][1]：至多 j 次额度且持股
        dp = [[0, NEG] for _ in range(k + 1)]
        for i in range(1, n + 1):
            p = prices[i - 1]
            ndp = [row[:] for row in dp]  # 先承接「今天不操作」
            for j in range(1, k + 1):
