def build(vals):
    if not vals or vals[0] == "null":
        return None
    root = TreeNode(int(vals[0]))
    queue = [root]
    head = 0
    i = 1
    while head < len(queue) and i < len(vals):
        node = queue[head]
        head += 1
        if i < len(vals):
            if vals[i] != "null":
