class Solution:
    def findTargetSumWays(self, nums: List[int], target: int) -> int:
        total = sum(nums)
        if abs(target) > total:
            return 0
        off = total  # 和的范围 [-total, total] 统一右移，避免负下标
        W = 2 * total + 1
        # dp[i][j]：用前 i 个数凑出和 (j - off) 的方案数
        dp = [[0] * W for _ in range(len(nums) + 1)]
        dp[0][off] = 1
        for i in range(1, len(nums) + 1):
            x = nums[i - 1]
            for j in range(W):
                if j - x >= 0:
                    dp[i][j] += dp[i - 1][j - x]
                if j + x < W:
                    dp[i][j] += dp[i - 1][j + x]
        return dp[len(nums)][target + off]

