class Solution:
    def lastStoneWeightII(self, stones: List[int]) -> int:
        total = sum(stones)
        half = total // 2
        n = len(stones)
        # dp[i][j]：前 i 块石头、容量 j 能装出的最大重量
        dp = [[0] * (half + 1) for _ in range(n + 1)]
        for i in range(1, n + 1):
            w = stones[i - 1]
            for j in range(half + 1):
                dp[i][j] = dp[i - 1][j]
                if j >= w:
                    dp[i][j] = max(dp[i][j], dp[i - 1][j - w] + w)
        return total - 2 * dp[n][half]

